// The control group of protocol/specs/src/errors/codes.json: why a request failed.
const (
	// The request's params are not what its method's schema admits. The error's
	// fields name each fault; JSON-RPC's own invalid-params code (-32602)
	// carries it.
	controlCodeInvalidParams = "control.invalid-params"

	// The request is written to a version of the control API this launcher does
	// not speak. The error's supported field names the ones it does.
	controlCodeUnsupportedApiVersion = "control.unsupported-api-version"

	// The launcher refuses the request as the command line refuses the same
	// options: they contradict each other, or do not apply to what they name.
	controlCodeInvalidRequest = "control.invalid-request"

	// The request names a service or a group the launcher has none of.
	controlCodeInvalidService = "control.invalid-service"

	// The launcher refuses a setting's value, as a start would refuse it. The
	// previous value is kept.
	controlCodeInvalidValue = "control.invalid-value"

	// The request names a setting the launcher does not keep.
	controlCodeUnknownSetting = "control.unknown-setting"

	// Several stacks could be meant and the request names none of them. The
	// error's choices name each; nothing was done.
	controlCodeTargetRequired = "control.target-required"

	// The root the request names is the basename of several registered roots.
	// The error's choices name each by its path; nothing was done.
	controlCodeTargetAmbiguous = "control.target-ambiguous"

	// The root the request names is not a knowledge base's clone: no such
	// directory, no .semiont/ in it, or a project file the launcher refuses.
	controlCodeRootNotFound = "control.root-not-found"

	// The root the request names is not in the registry.
	controlCodeRootNotRegistered = "control.root-not-registered"

	// The request needs a stack of its target recorded on this machine, and none
	// is.
	controlCodeStackNotRunning = "control.stack-not-running"

	// The request would change what a recorded stack depends on: stop the stack
	// first.
	controlCodeStackRunning = "control.stack-running"

	// Another semiont start of the same knowledge base holds its start lock.
	controlCodeStartInProgress = "control.start-in-progress"

	// No container runtime the request can use is on the launcher's PATH.
	controlCodeRuntimeUnavailable = "control.runtime-unavailable"

	// A program the request needs besides a container runtime (gh, for a
	// codespace) is not on the launcher's PATH.
	controlCodeDependencyUnavailable = "control.dependency-unavailable"

	// What the request needs to reach did not answer: the knowledge base, its
	// issuer, or a codespace's forward.
	controlCodeUnreachable = "control.unreachable"

	// The request would destroy something, and does not state that a person
	// confirmed it.
	controlCodeConfirmationRequired = "control.confirmation-required"

	// The launcher's own record of this machine (the stack record, the registry,
	// the sign-in store) cannot be read. Nothing was assumed in its place.
	controlCodeUnreadableState = "control.unreadable-state"

	// The launcher's stored session for the target is valid: there is nothing to
	// sign in to.
	controlCodeAlreadySignedIn = "control.already-signed-in"

	// The person was not signed in: the issuer refused or the code expired, the
	// gateway refused the token, or the session could not be kept. Nothing was
	// stored.
	controlCodeSignInFailed = "control.sign-in-failed"

	// The client cancelled the request before it ended.
	controlCodeCancelled = "control.cancelled"

	// The request failed for a reason no other code names. Its message says why,
	// as the command line would.
	controlCodeFailed = "control.failed"
)

// controlCodes: every code of the control group, in its order.
var controlCodes = []string{
	controlCodeInvalidParams,
	controlCodeUnsupportedApiVersion,
	controlCodeInvalidRequest,
	controlCodeInvalidService,
	controlCodeInvalidValue,
	controlCodeUnknownSetting,
	controlCodeTargetRequired,
	controlCodeTargetAmbiguous,
	controlCodeRootNotFound,
	controlCodeRootNotRegistered,
	controlCodeStackNotRunning,
	controlCodeStackRunning,
	controlCodeStartInProgress,
	controlCodeRuntimeUnavailable,
	controlCodeDependencyUnavailable,
	controlCodeUnreachable,
	controlCodeConfirmationRequired,
	controlCodeUnreadableState,
	controlCodeAlreadySignedIn,
	controlCodeSignInFailed,
	controlCodeCancelled,
	controlCodeFailed,
}
